TopUpResponse topUp(long userId, String key, TopUpRequest request) {
    // 1. Giữ chỗ cho key trước tiên, transaction ngắn; unique constraint quyết định ai thắng
    int inserted = jdbc.update("""
            insert into idempotency_records (user_id, key, request_hash, status, created_at)
            values (?, ?, ?, 'IN_PROGRESS', now())
            on conflict (user_id, key) do nothing""",
            userId, key, hash(request));
    if (inserted == 0) {
        IdempotencyRecord existing = idempotencyRepository.findByUserIdAndKey(userId, key).orElseThrow();
        if (!existing.requestHash().equals(hash(request))) throw new IdempotencyKeyReusedException(key); // 422
        if (existing.status() == IN_PROGRESS) throw new RequestInProgressException(key);               // 409, thử lại sau
        return existing.response();
    }

    // 2. Truyền tiếp key cho cổng thanh toán để chính nó cũng không trừ hai lần
    PaymentResult result;
    try {
        result = paymentGateway.charge(userId, request.amount(), key);
    } catch (CardDeclinedException e) {
        // lỗi nghiệp vụ: lưu lại để retry nhận đúng kết quả này, không kẹt ở IN_PROGRESS
        return idempotencyRepository.completeWithError(userId, key, TopUpResponse.declined(e));
    }
    // timeout thì để nguyên IN_PROGRESS cho job đối soát hỏi trạng thái ở cổng thanh toán

    // 3. Ghi tiền vào ví và đánh dấu hoàn thành trong cùng một transaction
    return transactionTemplate.execute(status -> {
        wallet.credit(userId, request.amount(), result.transactionId());
        TopUpResponse response = TopUpResponse.from(result);
        idempotencyRepository.complete(userId, key, response);
        return response;
    });
}
